module TopModule (
    input  clk,
    input  reset,
    input  x,
    output z
);

    // State encoding: 3 bits as specified in the table
    logic [2:0] y;          // present state
    logic [2:0] y_next;     // next state

    // Next-state logic (combinational)
    always_comb begin
        case (y)
            3'b000: begin
                if (x == 1'b0)
                    y_next = 3'b000;
                else
                    y_next = 3'b001;
            end
            3'b001: begin
                if (x == 1'b0)
                    y_next = 3'b001;
                else
                    y_next = 3'b100;
            end
            3'b010: begin
                if (x == 1'b0)
                    y_next = 3'b010;
                else
                    y_next = 3'b001;
            end
            3'b011: begin
                if (x == 1'b0)
                    y_next = 3'b001;
                else
                    y_next = 3'b010;
            end
            3'b100: begin
                if (x == 1'b0)
                    y_next = 3'b011;
                else
                    y_next = 3'b100;
            end
            default: y_next = 3'b000; // Should never happen with proper encoding
        endcase
    end

    // Output logic (combinational)
    // z = 1 for present states 011 and 100, else 0
    assign z = (y == 3'b011) | (y == 3'b100);

    // Sequential logic (positive-edge triggered, synchronous active-high reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;   // Reset to state 000
        else
            y <= y_next;
    end

endmodule

