module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the three received bytes
    logic [23:0] shift_reg;

    // -------------------------------------------------
    // FSM state transition logic (positive edge triggered)
    // -------------------------------------------------
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0;               // clear done each cycle

            case (state)
                IDLE: begin
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // first byte goes to [23:16]
                    end else begin
                        next_state <= IDLE;
                        // discard byte
                    end
                end

                BYTE1: begin
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // second byte -> [15:8]
                end

                BYTE2: begin
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};  // third byte -> [7:0]
                end

                BYTE3: begin
                    next_state <= IDLE;
                    done       <= 1'b1;                 // assert done this cycle
                    // shift_reg already holds the 3‑byte message
                end

                default: next_state <= IDLE;
            endcase
        end
    end

    // -------------------------------------------------
    // Output assignment – out_bytes is valid when done is high
    // -------------------------------------------------
    always_ff @(posedge clk) begin
        if (reset)
            out_bytes <= 24'b0;
        else if (done)
            out_bytes <= shift_reg;
        // out_bytes may hold whatever value at other times (don't‑care)
    end

endmodule

