module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the flip-flop output
    reg [2:0] q;

    // Flip-flop behavior: on posedge clk, if L is 1 load r_in, else shift
    always @(posedge clk) begin
        if (L) begin
            q <= {1'b0, 1'b0, r_in};  // Load r_in into the three bits
        end else begin
            // Shift right: new MSB is XOR of previous MSB and LSB,
            // middle bit becomes previous LSB, LSB becomes q_in
            q <= {q[2] ^ q[0], q[1], q_in};
        end
    end

    // Assign the output Q to the MSB of the internal register
    assign Q = q[2];

endmodule

