module TopModule (
    input  logic d,
    input  logic done_counting,
    input  logic ack,
    input  logic [9:0] state,
    output logic B3_next,
    output logic S_next,
    output logic S1_next,
    output logic Count_next,
    output logic Wait_next,
    output logic done,
    output logic counting,
    output logic shift_ena
);

    // One-hot encoded next state signals (combinational)
    logic [9:0] next_state;

    // State bits (one-hot)
    logic [9:0] S, S1, S11, S110, B0, B1, B2, B3, Count, Wait;

    // Assign current state from the one-hot encoding
    assign S      = state[0];
    assign S1     = state[1];
    assign S11    = state[2];
    assign S110   = state[3];
    assign B0     = state[4];
    assign B1     = state[5];
    assign B2     = state[6];
    assign B3     = state[7];
    assign Count  = state[8];
    assign Wait   = state[9];

    // ---------- Next-state logic (one-hot) ----------
    // Compute next_state by inspection of the state diagram.
    // The following equations are derived directly from the transition table.

    // S next: from S (d=0) and from S110 (d=0) and from Wait (ack=1)
    assign next_state[0] = (~d & S) | (~d & S110) | (ack & Wait);

    // S1 next: from S (d=1)
    assign next_state[1] = (d & S);

    // S11 next: from S1 (d=1)
    assign next_state[2] = (d & S1);

    // S110 next: from S11 (d=0)
    assign next_state[3] = (~d & S11);

    // B0 next: from S110 (d=1)
    assign next_state[4] = (d & S110);

    // B1 next: from B0 (always, as per diagram)
    assign next_state[5] = B0;

    // B2 next: from B1 (always)
    assign next_state[6] = B1;

    // B3 next: from B2 (always)
    assign next_state[7] = B2;

    // Count next: from B3 (always)
    assign next_state[8] = B3;

    // Wait next: from Count (done_counting=1) and from Wait (ack=0, done=1)
    assign next_state[9] = (~done_counting & Count) | (~ack & Wait & done);

    // ---------- Output signals (one-hot decode) ----------
    // B3_next: asserted when next state is B3
    assign B3_next = next_state[7];

    // S_next: asserted when next state is S
    assign S_next  = next_state[0];

    // S1_next: asserted when next state is S1
    assign S1_next = next_state[1];

    // Count_next: asserted when next state is Count
    assign Count_next = next_state[8];

    // Wait_next: asserted when next state is Wait
    assign Wait_next = next_state[9];

    // ---------- Output logic (Moore machine) ----------
    // shift_ena: active in B0, B1, B2, B3
    assign shift_ena = B0 | B1 | B2 | B3;

    // counting: active in Count state
    assign counting = Count;

    // done: active in Wait state (as per diagram: Wait (done=1))
    assign done = Wait;

endmodule

