module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // (1) out_both: in[i] AND in[i+1] for i = 0..2; out_both[3] is unused (tied to 0)
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = 1'b0;

    // (2) out_any: in[i] OR in[i-1] for i = 1..3; out_any[0] is unused (tied to 0)
    assign out_any[0] = 1'b0;
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];

    // (3) out_different: in[i] XOR in[i-1] with wrap-around (in[3] XOR in[0])
    assign out_different[0] = 1'b0;                // in[0] has no left neighbour (except wrap, but spec says out_any[0] unused; we keep consistency)
    assign out_different[1] = in[1] ^ in[0];
    assign out_different[2] = in[2] ^ in[1];
    assign out_different[3] = in[3] ^ in[0];       // wrap-around neighbour

