module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    //----------------------------------------------------------------
    // FSM state encoding (3 bits)
    //----------------------------------------------------------------
    typedef enum logic [2:0] {
        S_A   = 3'b000,  // beginning state (reset held)
        S_F1  = 3'b001,  // f = 1 for one cycle
        S_X1  = 3'b010,  // just saw x=1
        S_X10 = 3'b011,  // saw x=1,0
        S_G1  = 3'b100,  // g = 1, waiting for y=1 within 2 cycles
        S_G0  = 3'b101   // g = 0 permanently
    } state_t;

    //----------------------------------------------------------------
    // State register (synchronous, active-low reset)
    //----------------------------------------------------------------
    reg [2:0] state, next_state;

    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= S_A;
        else
            state <= next_state;
    end

    //----------------------------------------------------------------
    // Next‑state logic
    //----------------------------------------------------------------
    always_comb begin
        case (state)
            S_A: begin
                // As long as reset is asserted we stay in A.
                // When reset is de‑asserted we move to S_F1 after the
                // next clock edge.
                next_state = S_F1;
            end

            S_F1: begin
                // f is asserted for exactly one cycle, then go monitor x.
                next_state = S_X1;
            end

            S_X1: begin
                // We have just seen x=1.
                if (x)
                    next_state = S_X1;   // stay in X1 (consecutive 1)
                else
                    next_state = S_X10;  // saw 1,0
            end

            S_X10: begin
                // We have seen the pattern 1,0.
                if (x)
                    next_state = S_G1;   // now we have 1,0,1 -> trigger g
                else
                    next_state = S_X10;  // still waiting for the third 1
            end

            S_G1: begin
                // g = 1, we are waiting for y = 1 within at most 2 cycles.
                if (y)
                    next_state = S_G1;   // y became 1 – keep g = 1 forever
                else if (cnt == 2'b10)
                    next_state = S_G0;   // timeout – g = 0 forever
                else
                    next_state = S_G1;
            end

            S_G0: begin
                // g = 0 permanently until reset.
                next_state = S_G0;
            end

            default: next_state = S_A;
        endcase
    end

    //----------------------------------------------------------------
    // Output logic
    //----------------------------------------------------------------
    // f is 1 only in state S_F1 (one cycle after reset de‑assertion)
    assign f = (state == S_F1);

    // g is 1 in states S_G1, 0 otherwise (including S_G0 and reset)
    assign g = (state == S_G1);

    //----------------------------------------------------------------
    // Cycle counter for the “within two clock cycles” requirement
    //----------------------------------------------------------------
    // A simple 2‑bit counter that increments each cycle we stay in S_G1
    // without seeing y. When it reaches 2 we transition to S_G0.
    reg [1:0] cnt;
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            cnt <= 2'b00;
        end else begin
            case (state)
                S_G1: begin
                    if (y)
                        cnt <= 2'b00;   // y found – reset counter
                    else
                        cnt <= cnt + 1; // one more cycle without y
                end
                default: cnt <= 2'b00;
            endcase
        end
    end

    // Use the counter to decide the next state from S_G1
    always_comb begin
        case (state)
            S_G1: begin
                if (y || (cnt == 2'b10))
                    next_state = (y) ? S_G1 : S_G0;
                else
                    next_state = S_G1;
            end
            default: next_state = S_A;
        endcase
    end

endmodule

