module TopModule (
    input  clk,
    input  reset,
    input  slowena,
    output q [3:0]
);

    // Internal register for the counter
    reg [3:0] q_reg;

    // Combinational logic for next state
    wire [3:0] q_next;

    // Synchronous reset and enable logic
    always @(posedge clk) begin
        if (reset)
            q_reg <= 4'd0;
        else if (slowena)
            q_reg <= q_next;
        // If slowena is low, q_reg retains its current value
    end

    // Counter wraps around at 10 (binary 1010). 
    // When the count reaches 9 (1001) and increments, it should go to 0.
    // We achieve this by detecting the state 9 and forcing next state to 0.
    always @(*) begin
        if (q_reg == 4'd9)
            q_next = 4'd0;
        else
            q_next = q_reg + (slowena ? 4'd1 : 4'd0);
    end

    // Output assignment
    assign q = q_reg;

endmodule

Prob068_countbcd.code:
module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: ena[2] for hundreds, ena[1] for tens, ena[0] for ones
    output q     // 16 bits: q[3:0] ones, q[7:4] tens, q[11:8] hundreds, q[15:12] thousands
);

    // Internal 16-bit register for the BCD counter
    reg [15:0] q_reg;

    // Assign outputs
    assign q = q_reg;

    // Enable signals for the three upper digits
    // ena[0] -> ones digit always enabled (counter always counts)
    // ena[1] -> tens digit enabled when ones roll over from 9 to 0
    // ena[2] -> hundreds digit enabled when tens roll over from 9 to 0
    assign ena = {q_reg[11:8] == 4'd9, q_reg[7:4] == 4'd9, 1'b1};

    // Synchronous always block for the counter
    always @(posedge clk) begin
        if (reset)
            q_reg <= 16'd0;
        else begin
            // Compute carry from ones to tens
            // Carry occurs when ones digit is 9 and we are incrementing
            wire ones_carry = (q_reg[3:0] == 4'd9);

            // Increment ones digit (q[3:0])
            // If ones reach 9, reset to 0 and carry to tens; otherwise just add 1
            if (ones_carry)
                q_reg[3:0] <= 4'd0;
            else
                q_reg[3:0] <= q_reg[3:0] + 1'b1;

            // Tens digit (q[7:4]) increment logic
            // Increment tens if ones just rolled over (ones_carry is high)
            if (ones_carry)
                q_reg[7:4] <= q_reg[7:4] + 1'b1;
            else
                q_reg[7:4] <= q_reg[7:4];

            // Hundreds digit (q[11:8]) increment logic
            // Increment hundreds if tens rolled over (ones were 9 and tens were 9)
            // We detect tens roll-over by checking if tens were 9 and ones just rolled over.
            wire tens_carry = (q_reg[7:4] == 4'd9) & ones_carry;
            if (tens_carry)
                q_reg[11:8] <= q_reg[11:8] + 1'b1;
            else
                q_reg[11:8] <= q_reg[11:8];

            // Thousands digit (q[15:12]) increment logic
            // Increment thousands if hundreds rolled over.
            // Hundreds roll-over when tens_carry is high and hundreds were 9.
            wire hundreds_carry = (q_reg[11:8] == 4'd9) & tens_carry;
            if (hundreds_carry)
                q_reg[15:12] <= q_reg[15:12] + 1'b1;
            else
                q_reg[15:12] <= q_reg[15:12];
        end
    end

endmodule

