module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = B; // in don't-care, stays B
            C: next_state = in ? D : A;
            D: next_state = B; // in don't-care, goes to B
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine – output depends only on state)
    always_comb begin
        case (state)
            D: out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // State register (synchronous positive-edge triggered with active-high reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

Prob155_lemmings4.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Outputs (Moore machine)
    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = (state == FALLING);
    assign digging    = (state == DIGGING);

    // Internal registers for fall counter and direction memory
    reg [4:0] fall_cnt; // counts cycles in FALLING; >20 triggers splatter
    reg       fall_dir; // 0 = walking left before fall, 1 = walking right before fall
    reg       dig_dir;  // 0 = walking left before dig, 1 = walking right before dig

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            WALK_LEFT: begin
                if (!ground) begin
                    // Start falling – remember we were walking left
                    next_state = FALLING;
                end else if (dig) begin
                    // Start digging – remember we were walking left
                    next_state = DIGGING;
                end else if (bump_left | bump_right) begin
                    // Switch direction on bump
                    next_state = (bump_right) ? WALK_RIGHT : WALK_LEFT;
                end else begin
                    next_state = WALK_LEFT;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left | bump_right) begin
                    next_state = (bump_left) ? WALK_LEFT : WALK_RIGHT;
                end else begin
                    next_state = WALK_RIGHT;
                end
            end

            FALLING: begin
                if (ground) begin
                    // Ground re‑appeared
                    if (fall_cnt > 20) begin
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in the direction we were going before the fall
                        next_state = (fall_dir) ? WALK_RIGHT : WALK_LEFT;
                    end
                end else begin
                    // Still falling – stay in FALLING
                    next_state = FALLING;
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached the other side (ground = 0) – fall
                    next_state = FALLING;
                    // fall_dir will be updated in sequential block; we were walking in dig_dir
                end else if (dig) begin
                    next_state = DIGGING;
                end else begin
                    // Stop digging, resume walking in the same direction we had before digging
                    next_state = (dig_dir) ? WALK_RIGHT : WALK_LEFT;
                end
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
            end

            default: next_state = WALK_LEFT;
        endcase
    end

    // Sequential logic (positive edge triggered)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state                  <= WALK_LEFT;
            fall_cnt               <= 0;
            fall_dir               <= 1'b0; // WALK_LEFT
            dig_dir                <= 1'b0;
        end else begin
            state                  <= next_state;

            // Fall counter and direction update
            case (state)
                FALLING: begin
                    fall_cnt <= fall_cnt + 1;
                    // Remember the walking direction before we started falling
                    // (only set when we first enter FALLING from a walking state)
                    // We capture fall_dir based on the direction we were in before the transition.
                    // Since we are already in FALLING, we infer the direction from the
                    // previous walking state – here we simply propagate the stored fall_dir
                    // unless a reset occurs.
                end
                default: begin
                    // When leaving FALLING (to walking or splattered) we keep fall_cnt
                    // until next reset; the combinational next_state logic uses it.
                end
            endcase

            // Update fall_dir when we transition from WALK_LEFT/RIGHT into FALLING.
            // The simplest way: capture the direction based on the current state before
            // it changes. Because this is edge‑triggered, we can read `state` (the old state)
            // and `next_state` to decide fall_dir.
            if (next_state == FALLING && state == WALK_LEFT) begin
                fall_dir <= 1'b0; // was walking left
            end else if (next_state == FALLING && state == WALK_RIGHT) begin
                fall_dir <= 1'b1; // was walking right
            end
            // If we were already in FALLING, fall_dir keeps its previous value.

            // Digging direction update – when entering DIGGING from a walking state,
            // remember the walking direction.
            if (next_state == DIGGING && state == WALK_LEFT) begin
                dig_dir <= 1'b0; // was walking left
            end else if (next_state == DIGGING && state == WALK_RIGHT) begin
                dig_dir <= 1'b1; // was walking right
            end
            // If already in DIGGING, dig_dir retains its value.

            // Splattered state holds forever (no register updates needed beyond state)
        end
    end

    // Initial block for register reset (optional; areset handles it, but good practice)
    initial begin
        fall_cnt   <= 0;
        fall_dir   <= 1'b0;
        dig_dir    <= 1'b0;
    end

endmodule

