module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state: 2-bit counter representing the current water level index
    // 00 = below s[0] (max flow), 01 = between s[0] and s[1], 10 = between s[1] and s[2], 11 = above s[2] (min flow)
    reg [1:0] state;

    // Combinational logic to decode the current sensor state and update the outputs
    always @(*) begin
        // Default assignments (all outputs high = max flow / no flow)
        fr2 = 1'b1;
        fr1 = 1'b1;
        fr0 = 1'b1;
        dfr = 1'b0;

        case (state)
            2'b00: begin // Below s[0] (max flow)
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
                // dfr stays 0 as per max flow state (all valves open)
            end
            2'b01: begin // Between s[0] and s[1]
                fr0 = 1'b0; // Nominal flow fr0
                // fr1 and fr2 remain 1'b1 (not asserted)
            end
            2'b10: begin // Between s[1] and s[2]
                fr0 = 1'b0; // Nominal flow fr0
                fr1 = 1'b0; // Supplemental flow fr1 (level lower than previous change)
                // fr2 remains 1'b1
                dfr = 1'b1; // Indicate supplemental flow active
            end
            2'b11: begin // Above s[2] (min flow, zero input)
                // All outputs remain 1'b1 (no flow)
            end
        endcase
    end

    // Sequential logic to update state based on sensors and previous state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: state equivalent to long-time low water level
            state <= 2'b00;
        end else begin
            // Determine next state based on current sensors 's' and current state
            // Logic: If no sensors asserted (s == 3'b000) -> go to max flow (00)
            //         If above highest (s[2]==1) -> go to min flow (11)
            //         If between s[2] and s[1] (s==3'b110) -> go to mid-high (10)
            //         If between s[1] and s[0] (s==3'b101) -> go to mid-low (01)
            //         If below lowest (s==3'b001) -> stay at max flow (00)

            if (s == 3'b000) begin
                // No sensors: water level below lowest, max flow
                state <= 2'b00;
            end else if (s[2]) begin
                // Above highest sensor
                state <= 2'b11;
            end else if (s[1]) begin
                // Between s[2] and s[1] (s[1] is 1, s[2] is 0)
                state <= 2'b10;
            end else if (s[0]) begin
                // Between s[1] and s[0] (s[0] is 1, s[1] is 0)
                state <= 2'b01;
            end else begin
                // Fallback (should not be reached if s is valid 3-bit pattern)
                state <= 2'b00;
            end
        end
    end

endmodule
